import{d as r,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十章","description":"《正易心法》第二十章——六十四卦，唯乾与坤：太始气之始为乾、形之始为坤，本之自然、无所假合，其卦画纯一不驳、倒正不变，是名真体。","frontmatter":{"title":"正易心法·第二十章","description":"《正易心法》第二十章——六十四卦，唯乾与坤：太始气之始为乾、形之始为坤，本之自然、无所假合，其卦画纯一不驳、倒正不变，是名真体。","category":"guide","aliases":["正易心法第二十章","六十四卦唯乾与坤","真体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-20.md","filePath":"yijing/zheng-yi-xin-fa/chapter-20.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-20.md"},k=r({...c,setup(u){const i=[{id:"z20-01",label:"一、唯乾坤为真体",showLabel:!0,sentences:[["六十四卦，唯乾与坤。本之自然，是名",{text:"真体",glossary:"zhenti"},"。"]],note:["六十四卦之中，只有乾与坤；它们根本于自然，这就叫做「真体」。（这是全书的哲学收束之一——**「真体」是对第九至十六章所有论述的最终命名**：第九章乾坤破体生六子（破体的来源）、第十章乾坤纯粹（纯体的价值）、第十一章破体炼之（归真的路径）、第十六章乾坤倒正不变（真体的特性），本章给出最终的名字。）"]},{id:"z20-02",label:"二、气之始与形之始",showLabel:!0,sentences:[[{text:"太始",glossary:"taishi"},"者，气之始，是为乾。太始者，形之始，是为坤。"]],note:["太始，是气的开始，这就是乾；太始，是形的开始，这就是坤。（**这里原文两处都作「太始」，疑为传抄之误**——据《列子·天瑞》的宇宙生成序列：「太易（未见气）→ 太初（气之始）→ 太始（形之始）→ 太素（质之始）」，则「气之始」当为「太初」，「形之始」当为「太始」。**但意思很清楚：乾是气之初，坤是形之初**——乾坤不是圣人画出来的，而是宇宙生成过程中自然出现的结构：有气就有乾，有形就有坤。）"]},{id:"z20-03",label:"三、纯一不驳倒正不变",showLabel:!0,sentences:[["皆本之自然，无所",{text:"假合",glossary:"jiahe"},"也。故其卦画",{text:"纯一不驳",glossary:"chunyiBubo"},"，",{text:"倒正不变",glossary:"daozhengBubian"},"，是名真体。"]],note:["两者都根本于自然，没有借助任何东西拼合而成。因此它们的卦画纯粹统一、没有杂质，翻转与正立都不改变——这就叫做「真体」。（真体的四条完整定义：**① 本之自然**（来源：宇宙本原，非人为构造）；**② 无所假合**（结构：纯粹本质，非拼合而成）；**③ 纯一不驳**（卦画：六爻纯阳或纯阴）；**④ 倒正不变**（特性：翻转后仍是自身，即第十六章的「对体卦」）。对照六子：震坎艮巽离兑皆借乾坤之爻而成体，故曰「假合」。）"]}],o=[{id:"zhenti",term:"真体",pinyin:"zhēn tǐ",meaning:"真正的本体。相对于六子的「破体」，乾坤是未破之体。"},{id:"taishi",term:"太始",pinyin:"tài shǐ",meaning:"《列子·天瑞》宇宙生成序列之一。原文两处皆作「太始」，疑为传抄之误（气之始当为「太初」，形之始当为「太始」）。"},{id:"jiahe",term:"假合",pinyin:"jiǎ hé",meaning:"借助外力拼合而成。乾坤不需要借任何东西，故曰「无所假合」。"},{id:"chunyiBubo",term:"纯一不驳",pinyin:"chún yī bù bó",meaning:"纯粹统一，没有杂质。乾六爻全阳、坤六爻全阴，故纯一。驳是杂色。"},{id:"daozhengBubian",term:"倒正不变",pinyin:"dào zhèng bù biàn",meaning:"翻转与正立都不改变。即第十六章所说的「对体卦」特征。"}];return(b,a)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t("",21)),e(l,{colophon:"唯乾与坤 · 本之自然 · 纯一不驳 · 倒正不变",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文两处「太始」疑为传抄之误（参《列子·天瑞》：太初为气之始、太始为形之始），此处依底本录入、以上文说明校勘意见，不作径改。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"真体",pinyin:["zhēn","tǐ"],meaning:"真正的本体。相对于六子的「破体」，乾坤是未破之体。"},{term:"本之自然",pinyin:["běn","zhī"],meaning:"根本于自然，不是人为构造。乾坤是宇宙生成过程中自然出现的结构。"},{term:"无所假合",pinyin:["wú","suǒ"],meaning:"不借助任何东西拼合。六子皆借乾坤之爻而成体，唯乾坤自足。"},{term:"纯一不驳",pinyin:["chún","yī"],meaning:"纯粹统一，没有杂质。乾六爻全阳、坤六爻全阴。"},{term:"倒正不变",pinyin:["dào","zhèng"],meaning:"翻转与正立都不改变——即第十六章所说的「对体卦」特征。"}]}),a[3]||(a[3]=t("",24))])}}});export{y as __pageData,k as default};
